// src/services/stpApi.js
import axios from 'axios';
import { configService } from '@/services/configService';
import { showGlobalNotification } from '@/utils/notificationHandler.js';

// 创建 axios 实例
const apiClient = axios.create({
    baseURL: configService.getBackendBaseUrl(),
    timeout: 10000,
    headers: {
        'Content-Type': 'application/json; charset=utf-8'
    }
});

// 请求拦截器
apiClient.interceptors.request.use(
    (config) => {
        return config;
    },
    (error) => {
        return Promise.reject(error);
    }
);

// 响应拦截器
apiClient.interceptors.response.use(
    (response) => {
        return response;
    },
    (error) => {
        showGlobalNotification('API请求错误', 'error');
        return Promise.reject(error);
    }
);

// STP消息相关 API
export const stpApi = {
    // 发送STP消息
    sendMessage: async (targetAddr, message) => {
        try {
            const response = await apiClient.get('/api/stp/send', {
                params: {
                    target_addr: targetAddr,
                    message: message
                }
            });
            return response.data;
        } catch (error) {
            showGlobalNotification('发送STP消息失败', 'error');
            throw error;
        }
    },

    // 广播STP消息
    broadcastMessage: async (message, target = 'all') => {
        try {
            const response = await apiClient.get('/api/stp/broadcast', {
                params: {
                    message: message,
                    target: target
                }
            });
            return response.data;
        } catch (error) {
            showGlobalNotification('广播STP消息失败', 'error');
            throw error;
        }
    },

    // 发送摄像头控制命令
    sendCameraCommand: async (targetAddr, command) => {
        return await stpApi.sendMessage(targetAddr, command);
    },

    // 获取系统状态
    getSystemStatus: async () => {
        try {
            const response = await apiClient.get('/api/system/status');
            return response.data;
        } catch (error) {
            showGlobalNotification('获取系统状态失败', 'error');
            throw error;
        }
    }
};

// 摄像头相关 API
export const cameraApi = {
    // 获取摄像头流
    getStream: (serverIp, serverPort) => {
        return `${configService.getBackendBaseUrl()}/api/camera/stream?server_ip=${serverIp}&server_port=${serverPort}`;
    },

    // 获取中继流
    getRelayStream: (roomId) => {
        return `${configService.getBackendBaseUrl()}/api/camera/relay_stream?room_id=${roomId}`;
    },

    // 拍照
    capturePhoto: async () => {
        try {
            const response = await apiClient.get('/api/camera/capture');
            return response.data;
        } catch (error) {
            showGlobalNotification('拍照失败', 'error');
            throw error;
        }
    }
};

// 设备控制相关 API
export const deviceApi = {
    // 发送设备控制命令
    sendCommand: async (targetAddr, command) => {
        return await stpApi.sendMessage(targetAddr, command);
    },

    // 启动摄像头流
    startCameraStream: async (targetAddr) => {
        return await stpApi.sendCameraCommand(targetAddr, 'camera.stream.start');
    },

    // 停止摄像头流
    stopCameraStream: async (targetAddr) => {
        return await stpApi.sendCameraCommand(targetAddr, 'camera.stream.stop');
    },

    // 拍照
    capturePhoto: async (targetAddr) => {
        return await stpApi.sendCameraCommand(targetAddr, 'camera.capture');
    },

    // 启动中继流
    startRelayStreaming: async (target, ip, port) => {
        const command = `camera.start_relay_streaming ${ip} ${port}`;
        return await stpApi.broadcastMessage(command, target);
    }
};

// 错误处理工具函数
export const errorHandler = {
    // 处理API错误
    handleApiError: (error, defaultMessage = '请求失败') => {
        if (axios.isCancel(error)) {
            return '请求已取消';
        }
        if (error.response) {
            return `服务器错误: ${error.response.status}`;
        } else if (error.request) {
            return '网络错误，请检查网络连接';
        } else {
            return `${defaultMessage}: ${error.message}`;
        }
    }
};

// 工具函数
export const utils = {
    // 格式化时间
    formatTime: (timeStr) => {
        if (!timeStr) return '--';
        return timeStr.replace('T', ' ').substring(0, 19);
    },

    // 获取用户首字母
    getUserInitial: (email) => {
        return email ? email.charAt(0).toUpperCase() : 'U';
    },

    // 验证邮箱格式
    validateEmail: (email) => {
        const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
        return emailRegex.test(email);
    },

    // 验证密码长度
    validatePassword: (password) => {
        return password.length >= 6;
    }
};

export default {
    stpApi,
    cameraApi,
    deviceApi,
    errorHandler,
    utils
};
