<template>
    <div class="notification-manager" v-if="hasNotifications">
        <div class="scroll-container">
            <div class="notifications-container">
                <transition-group name="notification-list"
                                  move-class="notification-move"
                                  @mouseenter="handleMouseEnter"
                                  @mouseleave="handleMouseLeave"
                                  appear>
                    <Notification v-for="msg in messages"
                                  :key="msg.id"
                                  :message="msg.text"
                                  :type="msg.type"
                                  :id="msg.id"
                                  @dismiss="dismiss(msg.id)" />
                </transition-group>
            </div>
        </div>
    </div>
</template>

<script>
    import Notification from './Notification.vue';

    export default {
        components: {
            Notification
        },
        data() {
            return {
                messages: [],
                isHovering: false
            };
        },
        computed: {
            hasNotifications() {
                return this.messages.length > 0;
            }
        },
        methods: {
            addMessage(message, type = 'info') {
                const id = Date.now() + Math.random().toString(36).substr(2, 5);
                this.messages.unshift({ id, text: message, type });

                if (!this.isHovering) {
                    this.$nextTick(() => {
                        const container = this.$el?.querySelector('.scroll-container');
                        if (container) {
                            container.scrollTop = 0;
                        }
                    });
                }
            },
            dismiss(id) {
                this.messages = this.messages.filter(msg => msg.id !== id);
            },
            handleMouseEnter() {
                this.isHovering = true;
            },
            handleMouseLeave() {
                this.isHovering = false;
            }
        }
    };
</script>

