<template>
    <div id="app">
        <Header />
        <main class="container">
            <router-view v-slot="{ Component }">
                <transition name="fade" mode="out-in">
                    <component :is="Component" />
                </transition>
            </router-view>
        </main>
        <Footer />
        <NotificationManager ref="notificationManager" />
    </div>
</template>

<script>
    import Header from './components/Header.vue'
    import Footer from './components/Footer.vue'
    import NotificationManager from './components/NotificationManager.vue'
    import { setNotificationManager, setupGlobalNotificationHandling } from './utils/notificationHandler.js'

    export default {
        name: 'App',
        components: { Header, Footer, NotificationManager },
        mounted() {
            // 设置全局通知管理器
            setNotificationManager(this.$refs.notificationManager);
            // 初始化全局错误处理
            setupGlobalNotificationHandling();
        }
    }
</script>

<style>
    /* 全局样式重置 */
    * {
        margin: 0;
        padding: 0;
        box-sizing: border-box;
    }

    html, body {
        height: 100%;
        background-color: #f5f7fb; /* 全局背景色 */
    }

    #app {
        font-family: 'Poppins', sans-serif;
        display: flex;
        flex-direction: column;
        min-height: 100vh;
        background-color: white; /* 应用内容区域背景色 */
        box-shadow: 0 0 30px rgba(0, 0, 0, 0.05); /* 添加阴影增强层次感 */
    }

    /* 引入Google字体 */
    @import url('https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700&display=swap');
    @import url('https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.4.0/css/all.min.css');

    /* 定义CSS变量 */
    :root {
        --primary: #4361ee;
        --secondary: #3f37c9;
        --accent: #4895ef;
        --light: #f8f9fa;
        --dark: #212529;
        --success: #4cc9f0;
        --text: #343a40;
        --gray: #6c757d;
        --light-gray: #e9ecef;
        --shadow: 0 4px 12px rgba(0, 0, 0, 0.08);
        --transition: all 0.3s ease;
    }

    .container {
        flex: 1;
        /*        padding: 30px 0;*/
        width: 100%;
        margin: 0 auto;
    }

    /* 页面过渡动画 */
    .fade-enter-active,
    .fade-leave-active {
        transition: opacity 0.3s ease;
    }

    .fade-enter-from,
    .fade-leave-to {
        opacity: 0;
    }

    /* 响应式调整 */
    @media (max-width: 1400px) {
        #app {
            padding: 0 40px;
        }
    }

    @media (max-width: 992px) {
        #app {
            padding: 0 30px;
        }
    }

    @media (max-width: 768px) {
        #app {
            padding: 0 20px;
        }
    }

    @media (max-width: 480px) {
        #app {
            padding: 0 15px;
        }
    }
</style>