// src/services/macNicknameService.js

class MacNicknameService {
    constructor() {
        this.storageKey = 'mac_nicknames';
        this.defaultNicknames = {
            'ff:ff:ff:ff:ff:ff': '广播地址',
            '00:00:00:00:00:00': '未知设备'
        };
    }

    // 获取所有MAC地址昵称映射
    getNicknames() {
        try {
            const stored = localStorage.getItem(this.storageKey);
            if (stored) {
                return { ...this.defaultNicknames, ...JSON.parse(stored) };
            }
            return { ...this.defaultNicknames };
        } catch (error) {
            console.error('Error getting nicknames:', error);
            return { ...this.defaultNicknames };
        }
    }

    // 获取设备显示名称（备注 > 昵称 > MAC地址）
    getDeviceShowName(mac) {
        if (!mac) return '未知设备';
        
        const nicknames = this.getNicknames();
        if (nicknames[mac]) {
            return nicknames[mac];
        }
        
        // 如果没有备注，返回昵称短语
        return this.getDeviceNickname(mac);
    }

    // 获取设备昵称短语（用于target）
    getDeviceNickname(mac) {
        if (!mac) return '未知设备';
        
        // 直接使用base64编码生成短昵称
        try {
            // 将MAC地址转换为bytes
            const macClean = mac.replace(/[:-]/g, '');
            const macBytes = new Uint8Array(macClean.match(/.{2}/g).map(byte => parseInt(byte, 16)));
            
            // 转换为base64
            const base64String = btoa(String.fromCharCode(...macBytes));
            
            // 取前6个字符，替换特殊字符
            const sixCharString = base64String.slice(0, 6).replace(/\+/g, 'A').replace(/\//g, 'B');
            
            return sixCharString;
        } catch (error) {
            console.error('Error generating short nickname:', error);
            // 如果转换失败，返回传入的参数原值
            return mac;
        }
    }

    // 兼容旧方法
    getNickname(mac) {
        return this.getDeviceShowName(mac);
    }

    // 设置MAC地址昵称
    setNickname(mac, nickname) {
        try {
            const nicknames = this.getNicknames();
            
            // 移除默认昵称的覆盖
            if (this.defaultNicknames[mac]) {
                delete this.defaultNicknames[mac];
            }
            
            if (nickname) {
                nicknames[mac] = nickname;
            } else {
                delete nicknames[mac];
            }
            
            // 保存到本地存储
            const userNicknames = { ...nicknames };
            // 移除默认昵称，只保存用户设置的
            Object.keys(this.defaultNicknames).forEach(key => {
                delete userNicknames[key];
            });
            
            localStorage.setItem(this.storageKey, JSON.stringify(userNicknames));
            return true;
        } catch (error) {
            console.error('Error setting nickname:', error);
            return false;
        }
    }

    // 删除MAC地址昵称
    deleteNickname(mac) {
        try {
            const nicknames = this.getNicknames();
            delete nicknames[mac];
            
            // 保存到本地存储
            const userNicknames = { ...nicknames };
            Object.keys(this.defaultNicknames).forEach(key => {
                delete userNicknames[key];
            });
            
            localStorage.setItem(this.storageKey, JSON.stringify(userNicknames));
            return true;
        } catch (error) {
            console.error('Error deleting nickname:', error);
            return false;
        }
    }

    // 格式化MAC地址用于显示
    formatMacForDisplay(mac) {
        if (!mac) return '未知设备';
        
        // 只显示前8个字符
        const cleanedMac = mac.replace(/:/g, '');
        if (cleanedMac.length >= 8) {
            const shortMac = cleanedMac.substring(0, 8);
            return `${shortMac.substring(0, 4)}:${shortMac.substring(4, 8)}`;
        }
        return mac;
    }

    // 导入昵称（从JSON文件）
    importNicknames(jsonData) {
        try {
            const nicknames = typeof jsonData === 'string' ? JSON.parse(jsonData) : jsonData;
            if (typeof nicknames === 'object' && nicknames !== null) {
                localStorage.setItem(this.storageKey, JSON.stringify(nicknames));
                return true;
            }
            return false;
        } catch (error) {
            console.error('Error importing nicknames:', error);
            return false;
        }
    }

    // 导出昵称（为JSON字符串）
    exportNicknames() {
        try {
            const nicknames = this.getNicknames();
            // 移除默认昵称，只导出用户设置的
            const userNicknames = { ...nicknames };
            Object.keys(this.defaultNicknames).forEach(key => {
                delete userNicknames[key];
            });
            return JSON.stringify(userNicknames, null, 2);
        } catch (error) {
            console.error('Error exporting nicknames:', error);
            return '{}';
        }
    }

    // 清除所有用户设置的昵称
    clearAllNicknames() {
        try {
            localStorage.removeItem(this.storageKey);
            return true;
        } catch (error) {
            console.error('Error clearing nicknames:', error);
            return false;
        }
    }
}

// 导出单例
export const macNicknameService = new MacNicknameService();
export default macNicknameService;