// src/services/websocketService.js
import { configService } from '@/services/configService';
import { showGlobalNotification } from '@/utils/notificationHandler.js';

class WebSocketService {
    constructor() {
        this.topologySocket = null;
        this.messagesSocket = null;
        this.topologyCallbacks = [];
        this.messageCallbacks = [];
        this.reconnectAttempts = 0;
        this.maxReconnectAttempts = 5;
        this.reconnectDelay = 3000;
    }

    // 连接拓扑WebSocket
    connectTopology(forwardAddr = null, forwardMac = null) {
        if (this.topologySocket && this.topologySocket.readyState === WebSocket.OPEN) {
            return;
        }

        try {
            const path = `/ws/topology${forwardAddr ? `?forward_addr=${forwardAddr}${forwardMac ? `&forward_mac=${forwardMac}` : ''}` : ''}`;
            const url = configService.getWebSocketUrl(path);
            this.topologySocket = new WebSocket(url);

            this.topologySocket.onopen = () => {
                // Topology WebSocket connected
                this.reconnectAttempts = 0;
                // 发送刷新拓扑请求
                this.refreshTopology();
            };

            this.topologySocket.onmessage = (event) => {
                try {
                    // 检查消息是否可能是有效的JSON格式
                    const messageStr = event.data;
                    if (typeof messageStr !== 'string' || 
                        (!messageStr.trim().startsWith('{') && !messageStr.trim().startsWith('['))) {
                        // 不是有效的JSON格式，可能是连接确认消息，忽略
                        // Received non-JSON topology message:
                        return;
                    }
                    
                    const data = JSON.parse(messageStr);
                    this.topologyCallbacks.forEach(callback => callback(data));
                } catch (error) {
                    showGlobalNotification(`解析拓扑消息失败:\n${error.message}\n原消息:\n${event.data}`, 'error');
                }
            };

            this.topologySocket.onclose = () => {
                // Topology WebSocket disconnected
                this.attemptReconnect('topology', forwardAddr, forwardMac);
            };

            this.topologySocket.onerror = (error) => {
                showGlobalNotification('拓扑WebSocket错误', 'error');
            };
        } catch (error) {
            showGlobalNotification('连接拓扑WebSocket失败', 'error');
            this.attemptReconnect('topology', forwardAddr, forwardMac);
        }
    }

    // 连接消息WebSocket
    connectMessages() {
        if (this.messagesSocket && this.messagesSocket.readyState === WebSocket.OPEN) {
            return;
        }

        try {
            const url = configService.getWebSocketUrl('/ws/messages');
            this.messagesSocket = new WebSocket(url);

            this.messagesSocket.onopen = () => {
                // Messages WebSocket connected
                this.reconnectAttempts = 0;
            };

            this.messagesSocket.onmessage = (event) => {
                try {
                    // 检查消息是否可能是有效的JSON格式
                    const messageStr = event.data;
                    if (typeof messageStr !== 'string' || 
                        (!messageStr.trim().startsWith('{') && !messageStr.trim().startsWith('['))) {
                        // 不是有效的JSON格式，可能是连接确认消息，忽略
                        // Received non-JSON message:
                        return;
                    }
                    
                    const data = JSON.parse(messageStr);
                    this.messageCallbacks.forEach(callback => callback(data));
                } catch (error) {
                    showGlobalNotification('解析消息失败', 'error');
                }
            };

            this.messagesSocket.onclose = () => {
                // Messages WebSocket disconnected
                this.attemptReconnect('messages');
            };

            this.messagesSocket.onerror = (error) => {
                showGlobalNotification('消息WebSocket错误', 'error');
            };
        } catch (error) {
            showGlobalNotification('连接消息WebSocket失败', 'error');
            this.attemptReconnect('messages');
        }
    }

    // 尝试重连
    attemptReconnect(type, forwardAddr = null, forwardMac = null) {
        if (this.reconnectAttempts < this.maxReconnectAttempts) {
            this.reconnectAttempts++;
            // Attempting to reconnect WebSocket
            
            setTimeout(() => {
                if (type === 'topology') {
                    this.connectTopology(forwardAddr, forwardMac);
                } else if (type === 'messages') {
                    this.connectMessages();
                }
            }, this.reconnectDelay * this.reconnectAttempts);
        } else {
            showGlobalNotification(`${type} WebSocket重连失败`, 'error');
        }
    }

    // 刷新拓扑（获取全网拓扑）
    refreshTopology() {
        if (this.topologySocket && this.topologySocket.readyState === WebSocket.OPEN) {
            this.topologySocket.send(JSON.stringify({ refresh: true }));
        }
    }

    // 获取缓存拓扑
    getCachedTopology() {
        if (this.topologySocket && this.topologySocket.readyState === WebSocket.OPEN) {
            this.topologySocket.send(JSON.stringify({}));
        }
    }

    // 订阅拓扑更新
    subscribeTopology(callback) {
        if (!this.topologyCallbacks.includes(callback)) {
            this.topologyCallbacks.push(callback);
        }
    }

    // 取消订阅拓扑更新
    unsubscribeTopology(callback) {
        this.topologyCallbacks = this.topologyCallbacks.filter(cb => cb !== callback);
    }

    // 订阅消息
    subscribeMessages(callback) {
        if (!this.messageCallbacks.includes(callback)) {
            this.messageCallbacks.push(callback);
        }
    }

    // 取消订阅消息
    unsubscribeMessages(callback) {
        this.messageCallbacks = this.messageCallbacks.filter(cb => cb !== callback);
    }

    // 断开所有连接
    disconnectAll() {
        if (this.topologySocket) {
            this.topologySocket.close();
            this.topologySocket = null;
        }
        if (this.messagesSocket) {
            this.messagesSocket.close();
            this.messagesSocket = null;
        }
        this.topologyCallbacks = [];
        this.messageCallbacks = [];
    }

    // 发送消息（通过HTTP API）
    async sendSTPMessage(targetAddr, message) {
        try {
            const response = await fetch(`http://localhost:5002/api/stp/send?target_addr=${targetAddr}&message=${encodeURIComponent(message)}`);
            const data = await response.json();
            return data;
        } catch (error) {
            showGlobalNotification('发送STP消息失败', 'error');
            throw error;
        }
    }

    // 广播消息（通过HTTP API）
    async broadcastSTPMessage(message, target = 'all') {
        try {
            const response = await fetch(`http://localhost:5002/api/stp/broadcast?message=${encodeURIComponent(message)}&target=${target}`);
            const data = await response.json();
            return data;
        } catch (error) {
            showGlobalNotification('广播STP消息失败', 'error');
            throw error;
        }
    }
}

// 导出单例
export const websocketService = new WebSocketService();
export default websocketService;