<template>
  <Teleport to="body">
    <div
      v-if="visible"
      ref="menuRef"
      class="popup-menu"
      :class="{
        'menu-top': position === 'top',
        'menu-bottom': position === 'bottom',
        'menu-left': position === 'left',
        'menu-right': position === 'right'
      }"
      :style="menuStyle"
      @mouseenter="handleMouseEnter"
      @mouseleave="handleMouseLeave"
    >
      <div class="menu-items">
        <div
          v-for="(item, index) in items"
          :key="index"
          class="menu-item"
          @click="handleItemClick(item)"
          @mouseenter="handleItemMouseEnter(item, index)"
          @mouseleave="handleItemMouseLeave"
        >
          <span class="item-name">{{ item.name || 'Unnamed' }}</span>
          <span v-if="item.submenu" class="item-icon">
            <i class="fas fa-bars"></i>
          </span>
          <span v-else-if="item.input" class="item-icon">
            <i class="fas fa-edit"></i>
          </span>
        </div>
      </div>
      <!-- 子菜单 -->
      <PopupMenu
        v-if="activeSubmenu.items"
        v-model:visible="activeSubmenu.visible"
        :items="activeSubmenu.items"
        :trigger-element="activeSubmenu.triggerElement"
        :position="activeSubmenu.position"
        @item-click="handleSubmenuItemClick"
      />
    </div>
  </Teleport>
</template>

<script setup>
import { ref, computed, watch, nextTick } from 'vue';

const props = defineProps({
  visible: {
    type: Boolean,
    default: false
  },
  items: {
    type: Array,
    default: () => []
  },
  triggerElement: {
    type: Object,
    default: null
  },
  position: {
    type: String,
    default: 'right',
    validator: (value) => ['top', 'bottom', 'left', 'right'].includes(value)
  }
});

const emit = defineEmits(['update:visible', 'item-click']);

const menuRef = ref(null);
const activeSubmenu = ref({
  visible: false,
  items: null,
  triggerElement: null,
  position: 'right'
});
const mouseTimer = ref(null);

const menuStyle = computed(() => {
  if (!props.triggerElement) return {};

  const rect = props.triggerElement.getBoundingClientRect();
  const style = {
    position: 'fixed',
    zIndex: 9999
  };

  switch (props.position) {
    case 'top':
      style.bottom = `${window.innerHeight - rect.top + 8}px`;
      style.left = `${rect.left}px`;
      break;
    case 'bottom':
      style.top = `${rect.bottom + 8}px`;
      style.left = `${rect.left}px`;
      break;
    case 'left':
      style.top = `${rect.top}px`;
      style.right = `${window.innerWidth - rect.left + 8}px`;
      break;
    case 'right':
    default:
      style.top = `${rect.top}px`;
      style.left = `${rect.right + 8}px`;
      break;
  }

  return style;
});

const handleItemClick = (item) => {
  if (item.submenu) {
    // 展开子菜单
    activeSubmenu.value = {
      visible: true,
      items: item.submenu,
      triggerElement: menuRef.value,
      position: 'right'
    };
  } else {
    // 触发点击事件
    emit('item-click', item);
    // 关闭菜单
    emit('update:visible', false);
  }
};

const handleSubmenuItemClick = (item) => {
  emit('item-click', item);
};

const handleMouseEnter = () => {
  if (mouseTimer.value) {
    clearTimeout(mouseTimer.value);
    mouseTimer.value = null;
  }
};

const handleMouseLeave = () => {
  startCloseTimer();
};

const handleItemMouseEnter = (item, index) => {
  if (mouseTimer.value) {
    clearTimeout(mouseTimer.value);
    mouseTimer.value = null;
  }

  if (item.submenu) {
    // 自动展开子菜单
    const menuItem = menuRef.value.querySelectorAll('.menu-item')[index];
    activeSubmenu.value = {
      visible: true,
      items: item.submenu,
      triggerElement: menuItem,
      position: 'right'
    };
  }
};

const handleItemMouseLeave = () => {
  startCloseTimer();
};

const startCloseTimer = () => {
    if (mouseTimer.value) {
        clearTimeout(mouseTimer.value);
    }
    mouseTimer.value = setTimeout(() => {
        // 检查鼠标是否在任何菜单元素上
        const isMouseOverMenu = document.querySelector('.popup-menu:hover') !== null;
        if (!isMouseOverMenu) {
            emit('update:visible', false);
            activeSubmenu.value.visible = false;
        }
    }, 3000);
};

watch(() => props.visible, (newVal) => {
  if (!newVal) {
    activeSubmenu.value.visible = false;
    if (mouseTimer.value) {
      clearTimeout(mouseTimer.value);
      mouseTimer.value = null;
    }
  }
});
</script>

<style scoped>
.popup-menu {
  background: white;
  border: 1px solid #e0e0e0;
  border-radius: 6px;
  box-shadow: 0 2px 12px rgba(0, 0, 0, 0.15);
  padding: 4px 0;
  min-width: 120px;
  animation: menuFadeIn 0.2s ease;
}

@keyframes menuFadeIn {
  from {
    opacity: 0;
    transform: scale(0.95);
  }
  to {
    opacity: 1;
    transform: scale(1);
  }
}

.menu-items {
  display: flex;
  flex-direction: column;
}

.menu-item {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 8px 16px;
  cursor: pointer;
  transition: background-color 0.2s ease;
  white-space: nowrap;
}

.menu-item:hover {
  background-color: #f5f5f5;
}

.item-name {
  font-size: 14px;
  color: #333;
}

.item-icon {
  font-size: 12px;
  color: #999;
  margin-left: 8px;
}

.menu-item:hover .item-icon {
  color: #2196f3;
}

/* 位置样式 */
.menu-top {
  animation: slideDown 0.2s ease;
}

.menu-bottom {
  animation: slideUp 0.2s ease;
}

.menu-left {
  animation: slideRight 0.2s ease;
}

.menu-right {
  animation: slideLeft 0.2s ease;
}

@keyframes slideDown {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes slideUp {
  from {
    opacity: 0;
    transform: translateY(10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

@keyframes slideRight {
  from {
    opacity: 0;
    transform: translateX(-10px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}

@keyframes slideLeft {
  from {
    opacity: 0;
    transform: translateX(10px);
  }
  to {
    opacity: 1;
    transform: translateX(0);
  }
}
</style>