<template>
  <div class="tooltip-container" 
       @mouseenter="showTooltip" 
       @mouseleave="hideTooltip" 
       @mousemove="handleMouseMove">
    <slot></slot>
    <teleport to="body">
      <transition name="tooltip">
        <div v-if="isVisible || testMode" class="tooltip" ref="tooltipRef" :style="tooltipStyle">
          {{ testMode ? '测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.测试文本。Test text.' : content }}
        </div>
      </transition>
    </teleport>
  </div>
</template>

<script setup>
import { ref, computed, onMounted, onUnmounted } from 'vue';

const props = defineProps({
  content: {
    type: String,
    required: true
  },
  delay: {
    type: Number,
    default: 300
  },
  testMode: {
    type: Boolean,
    default: false
  }
});

const isVisible = ref(false);
const mousePosition = ref({ x: 0, y: 0 });
const tooltipRef = ref(null);
const tooltipSize = ref({ width: 200, height: 40 }); // 初始默认值
let showTimer = null;
let hideTimer = null;
const offset = 20;

// 获取tooltip实际大小
const getTooltipSize = () => {
  if (tooltipRef.value) {
    const rect = tooltipRef.value.getBoundingClientRect();
    tooltipSize.value = {
      width: rect.width,
      height: rect.height
    };
  }
};

// 监听可见性变化，获取tooltip大小
const updateTooltipPosition = () => {
  if (isVisible.value || props.testMode) {
    getTooltipSize();
  }
};

const tooltipStyle = computed(() => {
  const { x, y } = mousePosition.value;
  const windowWidth = window.innerWidth;
  const windowHeight = window.innerHeight;
  const { width, height } = tooltipSize.value;
  
  // 计算默认位置（右下角）
  let left = x + offset;
  let top = y + offset;
  
  // 边界检测
  // 如果右侧超出屏幕，显示在左侧
  if (left + width > windowWidth) {
    left = x - width - offset;
  }
  
  // 如果底部超出屏幕，显示在上方
  if (top + height > windowHeight) {
    top = y - height - offset;
  }
  
  // 确保不超出左侧屏幕
  if (left < 0) {
    left = offset;
  }
  
  // 确保不超出顶部屏幕
  if (top < 0) {
    top = offset;
  }
  
  return {
    position: 'fixed',
    left: `${left}px`,
    top: `${top}px`,
    zIndex: '1000',
    pointerEvents: 'none'
  };
});

const handleMouseMove = (event) => {
  mousePosition.value = {
    x: event.clientX,
    y: event.clientY
  };
  
  // 鼠标移动时更新tooltip大小和位置
  if (isVisible.value || props.testMode) {
    updateTooltipPosition();
  }
};

const showTooltip = () => {
  if (hideTimer) {
    clearTimeout(hideTimer);
    hideTimer = null;
  }
  
  if (!props.testMode) {
    showTimer = setTimeout(() => {
      isVisible.value = true;
      // 显示时获取tooltip大小
      setTimeout(updateTooltipPosition, 10); // 延迟一下确保DOM已更新
    }, props.delay);
  }
};

const hideTooltip = () => {
  if (showTimer) {
    clearTimeout(showTimer);
    showTimer = null;
  }
  
  if (!props.testMode) {
    hideTimer = setTimeout(() => {
      isVisible.value = false;
    }, 100);
  }
};

// 全局鼠标移动监听（用于测试模式）
const handleGlobalMouseMove = (event) => {
  if (props.testMode) {
    mousePosition.value = {
      x: event.clientX,
      y: event.clientY
    };
    // 更新tooltip大小和位置
    updateTooltipPosition();
  }
};

// 组件挂载时添加全局监听
onMounted(() => {
  if (props.testMode) {
    window.addEventListener('mousemove', handleGlobalMouseMove);
  }
});

// 组件卸载时清理
onUnmounted(() => {
  if (showTimer) clearTimeout(showTimer);
  if (hideTimer) clearTimeout(hideTimer);
  if (props.testMode) {
    window.removeEventListener('mousemove', handleGlobalMouseMove);
  }
});
</script>

