﻿﻿﻿﻿﻿﻿﻿﻿﻿﻿﻿// src/composables/useDeviceControl.js
import { ref, computed, onUnmounted, onMounted } from 'vue';
import { stpApi, deviceApi, utils } from '@/services/stpApi';
import { websocketService } from '@/services/websocketService';
import { macNicknameService } from '@/services/macNicknameService';
import { showGlobalNotification } from '@/utils/notificationHandler.js';

export function useDeviceControl() {
    // ========================= 响应式数据声明 =========================

    // 主题数据
    const topics = ref([]);
    const loadingTopics = ref(true);
    const selectedTopic = ref(null);

    // 消息数据
    const messages = ref([]);
    const loadingMessages = ref(false);

    // 主题详情
    const topicInfo = ref({});

    // 设备列表（使用字典存储，键是设备MAC地址，值是设备信息）
    const devices = ref({});
    const isDiscoveryWaiting = ref(false);

    // 设备分类存储
    const cloudDevices = ref([]);
    const monitorDevices = ref([]);
    const otherDevices = ref([]);

    // TCP连接设备
    const tcpConnections = ref({});

    // 拓扑相关状态
    const topology = ref({});
    const latestTopologyId = ref(null);
    const topologyLoading = ref(false);

    // 消息相关状态
    const messageDictionary = ref({
        'broadcast': [] // 广播消息
    });
    const messageLoading = ref(false);
    const selectedDeviceMac = ref(null);

    // 设备发现相关
    const deviceDiscoveryInterval = ref(null);
    const topologyCacheInterval = ref(null);
    const lastDiscoveryTime = ref(0);
    const DISCOVERY_INTERVAL = 30000;

    // ========================= 计算属性 =========================

    // 获取所有设备的计算属性（用于显示总数）
    const allDevices = computed(() => {
        return [
            ...(cloudDevices.value || []),
            ...(monitorDevices.value || []),
            ...(otherDevices.value || [])
        ];
    });

    // 按设备分组的消息列表（类似于QQ联系人）
    const groupedMessages = computed(() => {
        const deviceMessageList = [];
        
        // 确保'broadcast'键存在
        if (!messageDictionary.value['broadcast']) {
            messageDictionary.value['broadcast'] = [];
        }
        
        // 遍历消息字典的所有键
        Object.keys(messageDictionary.value).forEach(key => {
            const messages = messageDictionary.value[key];
            
            let deviceName;
            if (key === 'broadcast') {
                deviceName = '广播消息';
            } else {
                deviceName = macNicknameService.getNickname(key);
            }
            
            if (messages.length > 0) {
                // 按时间排序，最新的在前
                messages.sort((a, b) => (b.receivedAt || 0) - (a.receivedAt || 0));
                
                // 获取最新消息
                const latestMsg = messages[0];
                
                deviceMessageList.push({
                    mac: key,
                    deviceName: deviceName,
                    latestMessage: latestMsg,
                    messageCount: messages.length,
                    messages
                });
            } else if (key === 'broadcast') {
                // 即使'broadcast'没有消息，也显示在列表中
                deviceMessageList.push({
                    mac: key,
                    deviceName: deviceName,
                    latestMessage: {
                        msg: '暂无消息',
                        receivedAt: Date.now()
                    },
                    messageCount: 0,
                    messages: []
                });
            }
        });
        
        // 按最后消息时间排序
        deviceMessageList.sort((a, b) => {
            const timeA = a.latestMessage.receivedAt || 0;
            const timeB = b.latestMessage.receivedAt || 0;
            return timeB - timeA;
        });
        
        return deviceMessageList;
    });

    // 设备映射定义
    const deviceMappings = {
        types: {
            'cloud': '云设备',
            'monitor': '监控设备',
            'unknown': '未知设备'
        },
        icons: {
            'cloud': 'fas fa-cloud',
            'monitor': 'fas fa-desktop',
            'unknown': 'fas fa-question-circle'
        }
    };

    const deviceTypeMap = computed(() => deviceMappings.types);
    const deviceIconMap = computed(() => deviceMappings.icons);

    // 当前选中设备的消息列表
    const currentDeviceMessages = computed(() => {
        if (!selectedDeviceMac.value) {
            return [];
        }
        return messageDictionary.value[selectedDeviceMac.value] || [];
    });

    // ========================= 工具函数 =========================

    // 添加安全的JSON解析函数
    const safeJsonParse = (str) => {
        if (typeof str !== 'string') return str;

        try {
            // 先尝试直接解析
            return JSON.parse(str);
        } catch (e) {
            try {
                // 如果失败，尝试将单引号替换为双引号
                const fixedStr = str.replace(/'/g, '"');
                return JSON.parse(fixedStr);
            } catch (e2) {
                try {
                    // 如果还失败，尝试更严格的替换（处理键和值）
                    const strictFixedStr = str
                        .replace(/(\w+):/g, '"$1":') // 键加双引号
                        .replace(/'/g, '"'); // 值中的单引号替换为双引号
                    return JSON.parse(strictFixedStr);
                } catch (e3) {
                    showGlobalNotification('JSON解析失败，返回原始字符串', 'warning');
                    return str;
                }
            }
        }
    };

    // 添加时间戳转换函数
    const parseTimestamp = (timestamp) => {
        if (typeof timestamp === 'number') return timestamp;
        if (typeof timestamp === 'string') {
            const num = Number(timestamp);
            if (!isNaN(num)) return num;
        }
        return Math.floor(Date.now() / 1000); // 默认返回当前时间戳
    };

    // 消息比较函数 - 检查消息列表是否真的发生了变化
    const hasMessagesChanged = (oldMessages, newMessages) => {
        if (!oldMessages || !newMessages) return true;
        if (oldMessages.length !== newMessages.length) return true;

        // 比较最后几条消息的内容和时间
        const compareCount = Math.min(5, oldMessages.length, newMessages.length);
        for (let i = 0; i < compareCount; i++) {
            const oldMsg = oldMessages[oldMessages.length - 1 - i];
            const newMsg = newMessages[newMessages.length - 1 - i];

            if (oldMsg.msg !== newMsg.msg || oldMsg.time !== newMsg.time) {
                return true;
            }
        }

        return false;
    };

    // ========================= 设备发现相关函数 =========================

    // 发送设备发现消息（基于拓扑）
    const sendDiscoveryMessage = async () => {
        if (isDiscoveryWaiting.value) {
            // 跳过发送发现消息: 正在等待响应
            return;
        }

        try {
            // 标记开始等待设备响应
            isDiscoveryWaiting.value = true;
            lastDiscoveryTime.value = Math.floor(Date.now() / 1000);

            // 开始基于拓扑的设备发现
            // 直接刷新拓扑来获取设备信息
            refreshTopology();
            
            // 显示成功通知
            showGlobalNotification('设备发现开始，请稍候...', 'info');

            // 重置等待状态
            setTimeout(() => {
                isDiscoveryWaiting.value = false;
                // 设备发现等待状态结束
                showGlobalNotification('设备发现完成', 'success');
            }, 2000);

        } catch (error) {
            isDiscoveryWaiting.value = false;
            showGlobalNotification('设备发现失败', 'error');
        }
    };

    // 开始设备发现
    const startDeviceDiscovery = () => {
        stopDeviceDiscovery();

        // 立即发送一次发现消息（全网拓扑）
        sendDiscoveryMessage();

        // 设置定时发送发现消息（全网拓扑），每DISCOVERY_INTERVAL秒一次
        deviceDiscoveryInterval.value = setInterval(() => {
            if (!isDiscoveryWaiting.value) {
                sendDiscoveryMessage();
            }
        }, DISCOVERY_INTERVAL);

        // 设置定时发送空对象获取缓存拓扑，每秒一次
        topologyCacheInterval.value = setInterval(() => {
            if (websocketService.topologySocket && websocketService.topologySocket.readyState === WebSocket.OPEN) {
                websocketService.getCachedTopology();
            }
        }, 1000);
    };

    // 停止设备发现
    const stopDeviceDiscovery = () => {
        if (deviceDiscoveryInterval.value) {
            clearInterval(deviceDiscoveryInterval.value);
            deviceDiscoveryInterval.value = null;
        }
        if (topologyCacheInterval.value) {
            clearInterval(topologyCacheInterval.value);
            topologyCacheInterval.value = null;
        }
    };

    // ========================= 主题和消息相关函数 =========================

    // 修改 refreshSelectedTopic 函数，添加静默模式
    const refreshSelectedTopic = async (silent = false) => {
        // STP模式下简化处理
        if (!silent) {
            loadingMessages.value = true;
        }

        try {
            // 模拟获取消息
            // 实际项目中，这里应该从STP消息队列获取消息
            // 刷新消息...
            
            // 模拟消息数据
            const mockMessages = [
                {
                    msg: 'me',
                    time: Math.floor(Date.now() / 1000),
                    user: 'device1',
                    type: 'monitor'
                },
                {
                    msg: 'me',
                    time: Math.floor(Date.now() / 1000) - 1,
                    user: 'device2',
                    type: 'cloud'
                }
            ];

            if (hasMessagesChanged(messages.value, mockMessages)) {
                messages.value = mockMessages;
                // 消息已更新，数量:
                
                // 处理设备响应
                if (!isDiscoveryWaiting.value) {
                    processDeviceResponses();
                }
            } else {
                // 消息无变化，跳过更新
            }
        } catch (error) {
            showGlobalNotification('刷新消息失败', 'error');
            if (!silent) {
                messages.value = [];
            }
        } finally {
            if (!silent) {
                loadingMessages.value = false;
            }
        }
    };

    // 手动刷新
    const manualRefresh = async () => {
        await refreshSelectedTopic(false);
    };

    // 获取所有主题 - 简化版
    const fetchTopics = async () => {
        try {
            loadingTopics.value = true;
            // STP模式下简化处理，使用模拟数据
            topics.value = [
                {
                    topic: 'stp_topic',
                    name: 'STP消息通道',
                    type: 'STP'
                }
            ];
            if (topics.value.length > 0) {
                selectTopic(topics.value[0]);
            }
        } catch (error) {
            showGlobalNotification('获取主题列表失败', 'error');
            throw error;
        } finally {
            loadingTopics.value = false;
        }
    };

    // 获取主题详情 - 简化版
    const fetchTopicInfo = async (topic) => {
        try {
            // STP模式下简化处理
            topicInfo.value = {
                topic: topic.topic,
                name: topic.name,
                type: topic.type
            };
        } catch (error) {
            showGlobalNotification('获取主题详情失败', 'error');
        }
    };

    // 选择主题
    const selectTopic = (topic) => {
        selectedTopic.value = topic;
    };

    // 发布消息 - 使用STP消息
    const publishMessage = async (targetAddr, message) => {
        try {
            const response = await stpApi.sendMessage(targetAddr, message);
            if (response.success) {
                // 发布成功后立即刷新消息
                setTimeout(() => {
                    refreshSelectedTopic();
                }, 1000);
                showGlobalNotification('消息发布成功', 'success');
                return true;
            } else {
                showGlobalNotification('消息发布失败', 'error');
                return false;
            }
        } catch (error) {
            showGlobalNotification('消息发布失败', 'error');
            return false;
        }
    };

    // ========================= 生命周期和返回 =========================

    // 处理拓扑更新
    const handleTopologyUpdate = (data) => {
        if (data.topology) {
            topology.value = data.topology;
            latestTopologyId.value = data.topology_id;
            topologyLoading.value = false;
            // Topology updated:
            console.info(`Topology updated: ${data}`);
            
            // 从拓扑中提取设备信息
            extractDevicesFromTopology(data.topology, data.topology_id);
        }
    };

    // 从拓扑中提取设备信息
    const extractDevicesFromTopology = (topologyData, topologyId) => {
        // 使用topologyId作为时间戳（转换为秒）
        const topologyTime = Math.floor(topologyId / 1000);
        const currentTime = Math.floor(Date.now() / 1000);
        
        // 收集所有设备MAC地址（包括键和值中的）
        const allMacs = new Set();
        Object.keys(topologyData).forEach(mac => {
            allMacs.add(mac);
            // 收集值中的MAC地址
            Object.keys(topologyData[mac]).forEach(neighborMac => {
                allMacs.add(neighborMac);
            });
        });
        
        // 更新拓扑中的设备
        allMacs.forEach(mac => {
            if (topologyData[mac]) {
                // 存在于键中的设备，标记为在线
                // 生成昵称短语（6个字符）用于target
                const nicknamePhrase = macNicknameService.getDeviceNickname(mac);
                devices.value[mac] = {
                    ...devices.value[mac], // 保留原有信息
                    originalUser: devices.value[mac]?.originalUser || nicknamePhrase, // 存储昵称短语用于target
                    type: 'unknown', // 默认类型
                    time: topologyTime,
                    lastSeen: topologyTime,
                    status: 'online', // 拓扑中的设备默认为在线
                    mac: mac
                };
            } else {
                // 只存在于值中的设备，标记为通讯故障
                // 生成昵称短语（6个字符）用于target
                const nicknamePhrase = macNicknameService.getDeviceNickname(mac);
                devices.value[mac] = {
                    ...devices.value[mac], // 保留原有信息
                    originalUser: devices.value[mac]?.originalUser || nicknamePhrase, // 存储昵称短语用于target
                    type: 'unknown', // 默认类型
                    time: topologyTime,
                    lastSeen: topologyTime,
                    status: 'communication_failure', // 通讯故障
                    mac: mac
                };
            }
        });
        
        // 更新非拓扑设备的状态
        Object.keys(devices.value).forEach(mac => {
            if (!allMacs.has(mac)) {
                const device = devices.value[mac];
                const timeDiff = currentTime - device.lastSeen;
                
                if (timeDiff > 120) { // 超过2分钟
                    device.status = 'offline';
                } else if (timeDiff > 0) { // 2分钟内
                    device.status = 'suspect_offline';
                }
            }
        });
        
        // 更新TCP连接设备状态
        updateTcpConnectionDevices();
        
        // 更新设备列表
        updateDeviceLists();
    };

    // 更新TCP连接设备状态
    const updateTcpConnectionDevices = async () => {
        try {
            // 调用后端API获取TCP连接
            const response = await fetch('http://localhost:5002/api/stp/connections');
            if (response.ok) {
                const connections = await response.json();
                tcpConnections.value = connections;
                
                // 更新TCP连接设备的状态
                Object.values(connections).forEach(mac => {
                    if (devices.value[mac]) {
                        devices.value[mac].status = 'communicable'; // 可通讯状态
                    }
                });
            }
        } catch (error) {
            showGlobalNotification('获取TCP连接失败', 'error');
        }
    };

    // 更新设备列表
    const updateDeviceLists = () => {
        // 清空现有列表
        cloudDevices.value = [];
        monitorDevices.value = [];
        otherDevices.value = [];
        
        // 分类设备
        Object.values(devices.value).forEach(device => {
            if (device.type === 'cloud') {
                cloudDevices.value.push(device);
            } else if (device.type === 'monitor') {
                monitorDevices.value.push(device);
            } else {
                otherDevices.value.push(device);
            }
        });
        
        // 排序设备（按最后活跃时间）
        cloudDevices.value.sort((a, b) => b.lastSeen - a.lastSeen);
        monitorDevices.value.sort((a, b) => b.lastSeen - a.lastSeen);
        otherDevices.value.sort((a, b) => b.lastSeen - a.lastSeen);
    };

    // 处理消息更新
    const handleMessageUpdate = (data) => {
        if (data.message) {
            try {
                // 检查消息是否可能是有效的JSON格式
                const messageStr = data.message;
                if (typeof messageStr !== 'string' || 
                    (!messageStr.trim().startsWith('{') && !messageStr.trim().startsWith('['))) {
                    // 不是有效的JSON格式，可能是连接确认消息，忽略
                    // Received non-JSON message:
                    return;
                }
                
                const messageData = JSON.parse(messageStr);
                const processedMessage = {
                    ...messageData,
                    receivedAt: Date.now()
                };
                
                // 确定消息应该放入哪个键
                let targetKey;
                if (messageData.target === 'p2p' && messageData.source_mac) {
                    // P2P消息，按source_mac分组
                    targetKey = messageData.source_mac;
                } else {
                    // 广播消息，放入broadcast分组
                    targetKey = 'broadcast';
                }
                
                // 确保目标键存在
                if (!messageDictionary.value[targetKey]) {
                    messageDictionary.value[targetKey] = [];
                }
                
                // 添加到消息字典
                messageDictionary.value[targetKey].unshift(processedMessage);
                
                // 限制每个设备的消息数量
                if (messageDictionary.value[targetKey].length > 50) {
                    messageDictionary.value[targetKey] = messageDictionary.value[targetKey].slice(0, 50);
                }
                
                // 显示全局通知
                try {
                    // 获取设备显示名称
                    let deviceName = '未知设备';
                    if (messageData.source_mac) {
                        deviceName = getDeviceShowName(messageData.source_mac);
                    } else if (messageData.user) {
                        deviceName = messageData.user;
                    }
                    
                    // 获取消息内容
                    const messageContent = messageData.msg || '无内容';
                    
                    // 根据消息类型决定显示方式
                    let notificationMessage;
                    if (messageData.target === 'p2p') {
                        // p2p消息：直接显示消息内容
                        notificationMessage = `${deviceName}\n${messageContent}`;
                    } else {
                        // 其他消息：显示@设备名称 消息内容
                        notificationMessage = `${deviceName}\n@${messageData.target} ${messageContent}`;
                    }
                    
                    // 显示通知
                    showGlobalNotification(notificationMessage, 'info');
                } catch (error) {
                    console.error('Error showing message notification:', error);
                }
            } catch (error) {
                showGlobalNotification('解析消息失败', 'error');
            }
        }
    };

    // 刷新拓扑
    const refreshTopology = () => {
        topologyLoading.value = true;
        websocketService.refreshTopology();
    };

    // 选择设备
    const selectDeviceMac = (mac) => {
        selectedDeviceMac.value = mac;
    };

    // 设置设备备注
    const setDeviceNickname = (mac, nickname) => {
        return macNicknameService.setNickname(mac, nickname);
    };

    // 获取设备显示名称（备注 > 昵称 > MAC地址）
    const getDeviceShowName = (mac) => {
        return macNicknameService.getDeviceShowName(mac);
    };

    // 获取设备昵称短语（用于target）
    const getDeviceNickname = (mac) => {
        return macNicknameService.getDeviceNickname(mac);
    };

    // 初始化WebSocket连接
    const initWebSockets = () => {
        // 从本地存储加载拓扑设置
        const savedSettings = localStorage.getItem('topologySettings');
        let forwardAddr = null;
        let forwardMac = null;
        
        if (savedSettings) {
            try {
                const settings = JSON.parse(savedSettings);
                forwardAddr = settings.forward_addr || null;
                forwardMac = settings.forward_mac || null;
            } catch (e) {
                console.error('Failed to parse topology settings:', e);
            }
        }
        
        // 连接拓扑WebSocket
        websocketService.connectTopology(forwardAddr, forwardMac);
        websocketService.subscribeTopology(handleTopologyUpdate);
        
        // 连接消息WebSocket
        websocketService.connectMessages();
        websocketService.subscribeMessages(handleMessageUpdate);
    };

    // 组件挂载时初始化
    onMounted(() => {
        initWebSockets();
    });

    // 组件卸载时清理
    onUnmounted(() => {
        websocketService.disconnectAll();
    });

    return {
        // 状态
        topics,
        loadingTopics,
        selectedTopic,
        messages,
        loadingMessages,
        topicInfo,
        // 设备相关
        cloudDevices,
        monitorDevices,
        otherDevices,
        allDevices, // 新增计算属性
        isDiscoveryWaiting,
        // 拓扑相关
        topology,
        latestTopologyId,
        topologyLoading,
        // 消息相关
        messageDictionary,
        messageLoading,
        selectedDeviceMac,
        groupedMessages,
        currentDeviceMessages,

        // 方法
        fetchTopics,
        fetchTopicInfo,
        selectTopic,
        publishMessage,
        manualRefresh,
        sendDiscoveryMessage,
        formatTime: utils.formatTime,
        startDeviceDiscovery,
        stopDeviceDiscovery,
        // 新方法
        refreshTopology,
        setDeviceNickname,
        getDeviceNickname,
        getDeviceShowName,
        initWebSockets,
        selectDeviceMac
    };
}
